insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (90, 6, 46, 62, 'سورة الأنعام ٤٦ – ٦٢', 'لا تطرد الذين يدعون ربهم، و«سلام عليكم»، و«وعنده مفاتح الغيب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 90) = $j$[{"lbl": "الآيات ٤٦ – ٤٩", "q": "قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ ﴿٤٦﴾ قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّـٰلِمُونَ ﴿٤٧﴾ وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٤٨﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُواْ يَفۡسُقُونَ ﴿٤٩﴾", "w": [["أرأيتم", "أخبروني، وفي هذه الصيغة نوع من التعجب."], ["أخذ سمعكم وأبصاركم", "أصمّكم وأعماكم."], ["وختم على قلوبكم", "جعلها لا تعي ولا تفهم."], ["نصرّف الآيات", "ننوّع الأساليب لزيادة البيان والإيضاح."], ["يصدفون", "يُعرضون."], ["بغتة أو جهرة", "بغتة: بدون إعلام ولا علامة سابقة، والجهرة: ما كان بإعلام وعلامة تدل عليه."], ["هل يُهلك", "ما يُهلك."]], "m": "ما زال السياق في دعوة العادلين بربهم إلى التوحيد، فلقّن الله رسوله الحجة: قل أخبروني إن أخذ الله سمعكم فصرتم صمّاً، وأبصاركم فصرتم عمياً، وختم على قلوبكم فأصبحتم لا تعقلون، من إله غير الله يأتيكم به؟ لا أحد، فكيف تتركون عبادة من يملك ذلك كله، وتعبدون ما لا يملك شيئاً؟ انظر كيف ننوّع الآيات زيادةً في البيان، ثم هم يُعرضون. قل أخبروني إن أتاكم عذاب الله بغتة أو جهرة، هل يُهلك إلا القوم الظالمون بصرف العبادة إلى غير مستحقها؟ ثم عزّى رسوله: وما نرسل المرسلين إلا مبشّرين بالنجاة لمن آمن وعمل صالحاً، ومنذرين لمن كفر، فمن آمن وأصلح فلا خوف عليهم ولا هم يحزنون، والذين كذّبوا بآياتنا يمسّهم العذاب بما كانوا يفسقون، والفسق هو الذي أثمر لهم التكذيب.", "h": ["افتقار العبد إلى الله في سمعه وبصره وقلبه وفي كل حياته موجب عليه عبادة الله وحده.", "هلاك الظالمين لا مناص منه، عاجلاً أو آجلاً.", "بيان مهمة الرسل، وهي البشارة لمن أطاع والنذارة لمن عصى، والهداية والجزاء على الله.", "الفسق عن طاعة الله ورسوله ثمرة التكذيب."], "k": "لو أخذ الله سمعي أو بصري… فهل أستعملهما الآن فيما يرضيه، شكراً لمن لا يملكهما غيره؟"}, {"lbl": "الآيات ٥٠ – ٥٣", "q": "قُل لَّآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ لَكُمۡ إِنِّي مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُۚ أَفَلَا تَتَفَكَّرُونَ ﴿٥٠﴾ وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ ﴿٥١﴾ وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ ﴿٥٢﴾ وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّـٰكِرِينَ ﴿٥٣﴾", "w": [["خزائن", "جمع خزانة: ما يُخزن فيه الشيء ويُحفظ."], ["الغيب", "ما غاب عن العيون، وهو نوعان: حقيقي لا يعلمه إلا الله، وإضافي يعلمه بعض الخلق دون بعض."], ["وأنذر به", "خوّف به، أي بالقرآن."], ["بالغداة والعشيّ", "الغداة: من طلوع الفجر إلى طلوع الشمس، والعشيّ: من صلاة العصر إلى غروب الشمس."], ["فتطردهم", "تُبعدهم من مجلسك."], ["فتنّا بعضهم ببعض", "ابتلينا الغني بالفقير، والشريف بالوضيع."], ["منّ الله عليهم", "أعطاهم الفضل فهداهم إلى الإسلام."], ["بالشاكرين", "المستوجبين لفضل الله بسبب إيمانهم وصالح أعمالهم."]], "m": "ما زال السياق مع المنكرين للنبوة، فأمر الله رسوله أن يقول لهم: لا أقول لكم عندي خزائن الله فأعطيكم ما تقترحون، ولا أعلم الغيب فأخبركم بموعد العذاب، ولا أقول لكم إني ملك، إن أتّبع إلا ما يوحى إليّ، قل هل يستوي الأعمى والبصير؟ لا يستوي المؤمن والكافر، أفلا تتفكرون؟ وأمره أن ينذر بالقرآن الذين يخافون أن يُحشروا إلى ربهم، ليس لهم من دونه ولي ولا شفيع، فهؤلاء ينفعهم الإنذار لعلهم يتقون. واقترح بعض المشركين أن يُبعد من مجلسه فقراء المؤمنين كبلال وعمار وصهيب ليجلسوا إليه، فهمّ ﷺ رجاء هدايتهم، فنهاه ربه: ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه، ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء، فتطردهم فتكون من الظالمين، فصبر نفسه معهم. وكذلك فتنّا بعضهم ببعض، ليقول الأغنياء الشرفاء احتقاراً: أهؤلاء منّ الله عليهم من بيننا؟ أليس الله بأعلم بالشاكرين؟", "h": ["تقرير بشرية الرسول ﷺ.", "تقرير مبدأ أن الرسول ﷺ لا يعلم الغيب، وأنه لا يتصرّف في شيء من الكون.", "نفي مساواة المؤمن والكافر، إذ المؤمن مبصر والكافر أعمى.", "استحباب مجالسة أهل الفاقة وأهل التقوى والإيمان.", "بيان الحكمة في وجود أغنياء وفقراء، وأشراف ووضعاء، وأقوياء وضعفاء، وهي الاختبار.", "الشاكرون مستوجبون لزيادة النعم، والكافرون مستوجبون لنقصانها وذهابها."], "k": "«ولا تطرد الذين يدعون ربهم»… هل أُقرّب الفقير الصالح كما أُقرّب الغني الوجيه؟"}, {"lbl": "الآيات ٥٤ – ٥٨", "q": "وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ ﴿٥٤﴾ وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ ﴿٥٥﴾ قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ ﴿٥٦﴾ قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ ﴿٥٧﴾ قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّـٰلِمِينَ ﴿٥٨﴾", "w": [["سلام عليكم", "دعاء بالسلامة من كل مكروه، وهي تحية المؤمنين في الدنيا والآخرة."], ["كتب ربكم على نفسه الرحمة", "أوجب الرحمة على نفسه، فلذا لا يعذّب إلا بعد الإنذار، ويقبل توبة من تاب."], ["سوءاً", "ذنباً أساء به إلى نفسه."], ["بجهالة", "الجهالة أنواع، منها عدم تقدير عاقبة الذنب، ونسيان عظمة الرب."], ["ولتستبين", "تتضح وتظهر."], ["نُهيت", "نهاني ربي وزجرني عن عبادة أصنامكم."], ["بيّنة", "الحجة الواضحة العقلية الموجبة للحكم بالفعل أو الترك."], ["خير الفاصلين", "الفصل في الشيء: القضاء فيه، والفاصل: الحاكم في القضية ومنهيها."]], "m": "يرشد الله رسوله إلى الطريقة المثلى في الدعوة: وإذا جاءك الذين يؤمنون بآياتنا فرحّب بهم وقل: سلام عليكم، مهما كانت ذنوبهم، وأخبرهم أن ربهم كتب على نفسه الرحمة، أنه من عمل منكم سوءاً بجهالة ثم تاب من بعده فأقلع نادماً مستغفراً، وأصلح نفسه بالصالحات، فإنه غفور رحيم؛ هكذا يُستقبل كل من جاء مستفتياً يسأل عن طريق النجاة: بالبشر والطلاقة والسلام، لا بالعنف والتقريع. وكذلك نفصّل الآيات ليهتدي من أراد الهداية، ولتستبين سبيل المجرمين فتُجتنب. ثم أمره أن يقول للمشركين الذين يدعونه إلى موافقتهم: إني نُهيت أن أعبد الذين تدعون من دون الله، قل لا أتّبع أهواءكم، قد ضللت إذاً وما أنا من المهتدين، قل إني على بيّنة من ربي وكذّبتم به، ما عندي ما تستعجلون به من العذاب، إن الحكم إلا لله، يقصّ الحق وهو خير الفاصلين، قل لو أن عندي ما تستعجلون به لقُضي الأمر بيني وبينكم، والله أعلم بالظالمين.", "h": ["وجوب الرفق والتلطّف بالمستفتين، وعدم الشدة والغلظة عليهم.", "اتباع أهواء أهل الأهواء والباطل يُضلّ ويُهلك.", "على المسلم الداعي إلى ربه أن يكون على علم كافٍ بالله تعالى وبتوحيده ووعده ووعيده.", "وجوب الصبر والتحمّل لما يلقاه الداعي من أهل الزيغ والضلال من الاقتراحات الفاسدة."], "k": "«فقل سلام عليكم»… كيف أستقبل من جاءني تائباً أو سائلاً: ببِشر، أم بلوم وتقريع؟"}, {"lbl": "الآيات ٥٩ – ٦٢", "q": "۞وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ ﴿٥٩﴾ وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٦٠﴾ وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ ﴿٦١﴾ ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ ﴿٦٢﴾", "w": [["مفاتح الغيب", "جمع مَفتح، أي المخزن، فهي خزائن الغيب."], ["البر والبحر", "البر: اليابس من الأرض، والبحر: ما يغمره الماء منها."], ["ورقة", "واحدة الورق للشجر."], ["حبة", "واحدة الحب من ذرة أو بُرّ أو شعير أو غيرها."], ["ولا رطب", "الرطب ضد اليابس من كل شيء."], ["في كتاب مبين", "في اللوح المحفوظ، كتاب المقادير."], ["يتوفّاكم بالليل", "يُنيمكم باستتار الأرواح وحجبها عن الحياة كالموت."], ["ليُقضى أجل مسمّى", "يوقظكم لتواصلوا العمل إلى نهاية الأجل المسمّى لكم."], ["حفظة", "الكرام الكاتبين."], ["رسلنا", "ملك الموت وأعوانه."]], "m": "لما ذكر الله أنه أعلم بالظالمين، أخبر أن ذلك لأنه عالم الغيب والشهادة: وعنده مفاتح الغيب لا يعلمها إلا هو، ويعلم ما في البر والبحر، وما تسقط من ورقة إلا يعلمها، ولا حبة في ظلمات الأرض، ولا رطب ولا يابس إلا في كتاب مبين، أحصى كل شيء عدداً، فكيف لا يُعبد، وأين هو من تلك الأصنام الميتة؟ وهو الذي يتوفّاكم بالليل حال نومكم، ويعلم ما جرحتم بالنهار، ثم يبعثكم فيه ليُقضى أجل مسمّى، ثم إليه مرجعكم ثم ينبّئكم بما كنتم تعملون. وهو القاهر فوق عباده، ويرسل عليكم حفظة يكتبون أعمالكم، حتى إذا جاء أحدكم الموت توفّته رسلنا، ملك الموت وأعوانه، وهم لا يفرّطون. ثم رُدّوا إلى الله مولاهم الحق، ألا له الحكم وهو أسرع الحاسبين.", "h": ["بيان مظاهر القدرة والعلم والحكمة لله تعالى.", "استئثار الله تعالى بعلم الغيب.", "كتاب المقادير حوى كل شيء، حتى سقوط الورقة من الشجرة، وعلم الله بذلك.", "صحة إطلاق الوفاة على النوم، وبهذا فُسّر قوله تعالى لعيسى: «إني متوفّيك».", "تقرير مبدأ المعاد والحساب والجزاء."], "k": "«وما تسقط من ورقة إلا يعلمها»… ربي يعلم الورقة الساقطة، أفلا يعلم همّي الذي لم أبُح به لأحد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 90;
insert into public.tdb_cards(topic, i, body) select 90, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٦ – ٤٩", "q": "قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ ﴿٤٦﴾ قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّـٰلِمُونَ ﴿٤٧﴾ وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٤٨﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُواْ يَفۡسُقُونَ ﴿٤٩﴾", "w": [["أرأيتم", "أخبروني، وفي هذه الصيغة نوع من التعجب."], ["أخذ سمعكم وأبصاركم", "أصمّكم وأعماكم."], ["وختم على قلوبكم", "جعلها لا تعي ولا تفهم."], ["نصرّف الآيات", "ننوّع الأساليب لزيادة البيان والإيضاح."], ["يصدفون", "يُعرضون."], ["بغتة أو جهرة", "بغتة: بدون إعلام ولا علامة سابقة، والجهرة: ما كان بإعلام وعلامة تدل عليه."], ["هل يُهلك", "ما يُهلك."]], "m": "ما زال السياق في دعوة العادلين بربهم إلى التوحيد، فلقّن الله رسوله الحجة: قل أخبروني إن أخذ الله سمعكم فصرتم صمّاً، وأبصاركم فصرتم عمياً، وختم على قلوبكم فأصبحتم لا تعقلون، من إله غير الله يأتيكم به؟ لا أحد، فكيف تتركون عبادة من يملك ذلك كله، وتعبدون ما لا يملك شيئاً؟ انظر كيف ننوّع الآيات زيادةً في البيان، ثم هم يُعرضون. قل أخبروني إن أتاكم عذاب الله بغتة أو جهرة، هل يُهلك إلا القوم الظالمون بصرف العبادة إلى غير مستحقها؟ ثم عزّى رسوله: وما نرسل المرسلين إلا مبشّرين بالنجاة لمن آمن وعمل صالحاً، ومنذرين لمن كفر، فمن آمن وأصلح فلا خوف عليهم ولا هم يحزنون، والذين كذّبوا بآياتنا يمسّهم العذاب بما كانوا يفسقون، والفسق هو الذي أثمر لهم التكذيب.", "h": ["افتقار العبد إلى الله في سمعه وبصره وقلبه وفي كل حياته موجب عليه عبادة الله وحده.", "هلاك الظالمين لا مناص منه، عاجلاً أو آجلاً.", "بيان مهمة الرسل، وهي البشارة لمن أطاع والنذارة لمن عصى، والهداية والجزاء على الله.", "الفسق عن طاعة الله ورسوله ثمرة التكذيب."], "k": "لو أخذ الله سمعي أو بصري… فهل أستعملهما الآن فيما يرضيه، شكراً لمن لا يملكهما غيره؟"}, {"lbl": "الآيات ٥٠ – ٥٣", "q": "قُل لَّآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ لَكُمۡ إِنِّي مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُۚ أَفَلَا تَتَفَكَّرُونَ ﴿٥٠﴾ وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ ﴿٥١﴾ وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ ﴿٥٢﴾ وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّـٰكِرِينَ ﴿٥٣﴾", "w": [["خزائن", "جمع خزانة: ما يُخزن فيه الشيء ويُحفظ."], ["الغيب", "ما غاب عن العيون، وهو نوعان: حقيقي لا يعلمه إلا الله، وإضافي يعلمه بعض الخلق دون بعض."], ["وأنذر به", "خوّف به، أي بالقرآن."], ["بالغداة والعشيّ", "الغداة: من طلوع الفجر إلى طلوع الشمس، والعشيّ: من صلاة العصر إلى غروب الشمس."], ["فتطردهم", "تُبعدهم من مجلسك."], ["فتنّا بعضهم ببعض", "ابتلينا الغني بالفقير، والشريف بالوضيع."], ["منّ الله عليهم", "أعطاهم الفضل فهداهم إلى الإسلام."], ["بالشاكرين", "المستوجبين لفضل الله بسبب إيمانهم وصالح أعمالهم."]], "m": "ما زال السياق مع المنكرين للنبوة، فأمر الله رسوله أن يقول لهم: لا أقول لكم عندي خزائن الله فأعطيكم ما تقترحون، ولا أعلم الغيب فأخبركم بموعد العذاب، ولا أقول لكم إني ملك، إن أتّبع إلا ما يوحى إليّ، قل هل يستوي الأعمى والبصير؟ لا يستوي المؤمن والكافر، أفلا تتفكرون؟ وأمره أن ينذر بالقرآن الذين يخافون أن يُحشروا إلى ربهم، ليس لهم من دونه ولي ولا شفيع، فهؤلاء ينفعهم الإنذار لعلهم يتقون. واقترح بعض المشركين أن يُبعد من مجلسه فقراء المؤمنين كبلال وعمار وصهيب ليجلسوا إليه، فهمّ ﷺ رجاء هدايتهم، فنهاه ربه: ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه، ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء، فتطردهم فتكون من الظالمين، فصبر نفسه معهم. وكذلك فتنّا بعضهم ببعض، ليقول الأغنياء الشرفاء احتقاراً: أهؤلاء منّ الله عليهم من بيننا؟ أليس الله بأعلم بالشاكرين؟", "h": ["تقرير بشرية الرسول ﷺ.", "تقرير مبدأ أن الرسول ﷺ لا يعلم الغيب، وأنه لا يتصرّف في شيء من الكون.", "نفي مساواة المؤمن والكافر، إذ المؤمن مبصر والكافر أعمى.", "استحباب مجالسة أهل الفاقة وأهل التقوى والإيمان.", "بيان الحكمة في وجود أغنياء وفقراء، وأشراف ووضعاء، وأقوياء وضعفاء، وهي الاختبار.", "الشاكرون مستوجبون لزيادة النعم، والكافرون مستوجبون لنقصانها وذهابها."], "k": "«ولا تطرد الذين يدعون ربهم»… هل أُقرّب الفقير الصالح كما أُقرّب الغني الوجيه؟"}, {"lbl": "الآيات ٥٤ – ٥٨", "q": "وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ ﴿٥٤﴾ وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ ﴿٥٥﴾ قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ ﴿٥٦﴾ قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ ﴿٥٧﴾ قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّـٰلِمِينَ ﴿٥٨﴾", "w": [["سلام عليكم", "دعاء بالسلامة من كل مكروه، وهي تحية المؤمنين في الدنيا والآخرة."], ["كتب ربكم على نفسه الرحمة", "أوجب الرحمة على نفسه، فلذا لا يعذّب إلا بعد الإنذار، ويقبل توبة من تاب."], ["سوءاً", "ذنباً أساء به إلى نفسه."], ["بجهالة", "الجهالة أنواع، منها عدم تقدير عاقبة الذنب، ونسيان عظمة الرب."], ["ولتستبين", "تتضح وتظهر."], ["نُهيت", "نهاني ربي وزجرني عن عبادة أصنامكم."], ["بيّنة", "الحجة الواضحة العقلية الموجبة للحكم بالفعل أو الترك."], ["خير الفاصلين", "الفصل في الشيء: القضاء فيه، والفاصل: الحاكم في القضية ومنهيها."]], "m": "يرشد الله رسوله إلى الطريقة المثلى في الدعوة: وإذا جاءك الذين يؤمنون بآياتنا فرحّب بهم وقل: سلام عليكم، مهما كانت ذنوبهم، وأخبرهم أن ربهم كتب على نفسه الرحمة، أنه من عمل منكم سوءاً بجهالة ثم تاب من بعده فأقلع نادماً مستغفراً، وأصلح نفسه بالصالحات، فإنه غفور رحيم؛ هكذا يُستقبل كل من جاء مستفتياً يسأل عن طريق النجاة: بالبشر والطلاقة والسلام، لا بالعنف والتقريع. وكذلك نفصّل الآيات ليهتدي من أراد الهداية، ولتستبين سبيل المجرمين فتُجتنب. ثم أمره أن يقول للمشركين الذين يدعونه إلى موافقتهم: إني نُهيت أن أعبد الذين تدعون من دون الله، قل لا أتّبع أهواءكم، قد ضللت إذاً وما أنا من المهتدين، قل إني على بيّنة من ربي وكذّبتم به، ما عندي ما تستعجلون به من العذاب، إن الحكم إلا لله، يقصّ الحق وهو خير الفاصلين، قل لو أن عندي ما تستعجلون به لقُضي الأمر بيني وبينكم، والله أعلم بالظالمين.", "h": ["وجوب الرفق والتلطّف بالمستفتين، وعدم الشدة والغلظة عليهم.", "اتباع أهواء أهل الأهواء والباطل يُضلّ ويُهلك.", "على المسلم الداعي إلى ربه أن يكون على علم كافٍ بالله تعالى وبتوحيده ووعده ووعيده.", "وجوب الصبر والتحمّل لما يلقاه الداعي من أهل الزيغ والضلال من الاقتراحات الفاسدة."], "k": "«فقل سلام عليكم»… كيف أستقبل من جاءني تائباً أو سائلاً: ببِشر، أم بلوم وتقريع؟"}, {"lbl": "الآيات ٥٩ – ٦٢", "q": "۞وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ ﴿٥٩﴾ وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٦٠﴾ وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ ﴿٦١﴾ ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ ﴿٦٢﴾", "w": [["مفاتح الغيب", "جمع مَفتح، أي المخزن، فهي خزائن الغيب."], ["البر والبحر", "البر: اليابس من الأرض، والبحر: ما يغمره الماء منها."], ["ورقة", "واحدة الورق للشجر."], ["حبة", "واحدة الحب من ذرة أو بُرّ أو شعير أو غيرها."], ["ولا رطب", "الرطب ضد اليابس من كل شيء."], ["في كتاب مبين", "في اللوح المحفوظ، كتاب المقادير."], ["يتوفّاكم بالليل", "يُنيمكم باستتار الأرواح وحجبها عن الحياة كالموت."], ["ليُقضى أجل مسمّى", "يوقظكم لتواصلوا العمل إلى نهاية الأجل المسمّى لكم."], ["حفظة", "الكرام الكاتبين."], ["رسلنا", "ملك الموت وأعوانه."]], "m": "لما ذكر الله أنه أعلم بالظالمين، أخبر أن ذلك لأنه عالم الغيب والشهادة: وعنده مفاتح الغيب لا يعلمها إلا هو، ويعلم ما في البر والبحر، وما تسقط من ورقة إلا يعلمها، ولا حبة في ظلمات الأرض، ولا رطب ولا يابس إلا في كتاب مبين، أحصى كل شيء عدداً، فكيف لا يُعبد، وأين هو من تلك الأصنام الميتة؟ وهو الذي يتوفّاكم بالليل حال نومكم، ويعلم ما جرحتم بالنهار، ثم يبعثكم فيه ليُقضى أجل مسمّى، ثم إليه مرجعكم ثم ينبّئكم بما كنتم تعملون. وهو القاهر فوق عباده، ويرسل عليكم حفظة يكتبون أعمالكم، حتى إذا جاء أحدكم الموت توفّته رسلنا، ملك الموت وأعوانه، وهم لا يفرّطون. ثم رُدّوا إلى الله مولاهم الحق، ألا له الحكم وهو أسرع الحاسبين.", "h": ["بيان مظاهر القدرة والعلم والحكمة لله تعالى.", "استئثار الله تعالى بعلم الغيب.", "كتاب المقادير حوى كل شيء، حتى سقوط الورقة من الشجرة، وعلم الله بذلك.", "صحة إطلاق الوفاة على النوم، وبهذا فُسّر قوله تعالى لعيسى: «إني متوفّيك».", "تقرير مبدأ المعاد والحساب والجزاء."], "k": "«وما تسقط من ورقة إلا يعلمها»… ربي يعلم الورقة الساقطة، أفلا يعلم همّي الذي لم أبُح به لأحد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (91, 6, 63, 79, 'سورة الأنعام ٦٣ – ٧٩', '«قل من ينجيكم»، والإعراض عن الخائضين، وإبراهيم ﵇ يرى ملكوت السماوات', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 91) = $j$[{"lbl": "الآيات ٦٣ – ٦٧", "q": "قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿٦٣﴾ قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ ﴿٦٤﴾ قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ ﴿٦٥﴾ وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ ﴿٦٦﴾ لِّكُلِّ نَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ ﴿٦٧﴾", "w": [["ينجيكم", "يخلّصكم مما تخافون."], ["تضرّعاً وخفية", "التضرع: الدعاء بتذلّل، وخفية: بدون جهر بالدعاء."], ["من هذه", "أي من هذه المهلكة."], ["من الشاكرين", "المعترفين بفضلك، الحامدين لك على فعلك."], ["كرب", "الشدة الموجبة للحزن وألم الجسم والنفس."], ["تشركون", "أي به تعالى، بدعائكم أصنامكم وتقرّبكم إليها بالذبائح."], ["من فوقكم", "كالصواعق ونحوها."], ["من تحت أرجلكم", "كالزلازل والخسف ونحوهما."], ["أو يلبسكم شيعاً", "يخلط عليكم أمركم فتختلفون شيعاً وأحزاباً."], ["ويذيق بعضكم بأس بعض", "يقتل بعضكم بعضاً، فتذيق كل طائفة الأخرى ألم الحرب."], ["يفقهون", "يفهمون معاني ما نقول لهم."], ["وكذّب به قومك", "أي قريش."], ["الوكيل", "من يوكَل إليه الأمر يدبّره."], ["لكل نبأ مستقر", "المستقر: موضع الاستقرار، والنبأ: الخبر العظيم."]], "m": "ما زال السياق مع المشركين: قل لهم من ينجيكم من ظلمات البر والبحر؟ إذا ضلّ أحدكم طريقه في الصحراء وأظلم عليه الليل، أو ركب البحر فغشيته الظلمات واضطربت نفسه، يدعو من؟ يدعو الله وحده متضرّعاً جهراً وسراً: لئن أنجانا من هذه لنكوننّ من الشاكرين. قل الله ينجيكم منها ومن كل كرب، ثم يا للعجب أنتم تشركون به أصنامكم! قل هو القادر على أن يبعث عليكم عذاباً من فوقكم أو من تحت أرجلكم، أو يخلط عليكم أمركم فتصبحوا شيعاً وفرقاً متعادية يقتل بعضكم بعضاً. انظر كيف ننوّع الكلام ونوضّح معانيه رجاء أن يفقهوا فيهتدوا. وكذّب به قومك وهو الحق، قل لست عليكم بوكيل، ولكل نبأ مستقر وسوف تعلمون، وقد استقر نبؤه يوم بدر.", "h": ["لا برهان أعظم على بطلان الشرك من أن المشركين يُخلصون الدعاء لله تعالى في الشدة.", "لا منجى من الشدائد ولا منقذ من الكروب إلا الله سبحانه وتعالى.", "التحذير من الاختلاف المفضي إلى الانقسام والتكتل."], "k": "في الشدة لا أدعو إلا الله… فهل بقيت على الإخلاص نفسه بعد أن نجّاني؟"}, {"lbl": "الآيات ٦٨ – ٧٠", "q": "وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٦٨﴾ وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ ﴿٦٩﴾ وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ وَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ ﴿٧٠﴾", "w": [["يخوضون في آياتنا", "يتكلمون في القرآن طعناً فيه ونقداً له ولما جاء فيه."], ["بعد الذكرى", "بعد التذكّر."], ["ولكن ذكرى", "أي موعظة لهم."], ["وذر الذين", "اترك الكافرين."], ["لعباً ولهواً", "لعباً لأنهم لا يجنون منه فائدة قط، ولهواً لأنهم يتلهّون به عن الدين الحق."], ["أن تُبسل نفس", "تُسلم فتؤخذ فتُحبس في جهنم."], ["كل عدل", "العدل هنا: الفداء."], ["أُبسلوا", "حُبسوا في جهنم بما كسبوا من الشرك والمعاصي."], ["من حميم", "الماء الشديد الحرارة الذي لا يطاق."], ["وعذاب أليم", "شديد الألم والإيجاع، وهو عذاب النار."]], "m": "يقول الله لرسوله: وإذا رأيت الذين يخوضون في آياتنا يستهزئون بها ويسخرون مما دلّت عليه، فأعرض عنهم وانصرف حتى يخوضوا في حديث غيره، وإن أنساك الشيطان فجلست ثم ذكرت فقم ولا تقعد مع القوم الظالمين. وليس على المتقين من تبعة حسابهم شيء، ولكن إذا خاضوا في الباطل فقوموا ليكون ذلك ذكرى لهم فيكفّوا. وكان هذا بمكة قبل قوة الإسلام، ثم نزل بالمدينة النهي عن الجلوس معهم إذا خاضوا، وأن من جلس معهم كان مثلهم. وذر الذين اتخذوا دينهم لعباً ولهواً وغرّتهم الحياة الدنيا، وذكّر بالقرآن كي لا تُسلم نفس للعذاب بما كسبت، ليس لها من دون الله ولي ولا شفيع، وإن تقدّم كل فداء ولو ملء الأرض ذهباً لا يؤخذ منها. أولئك الذين أُبسلوا بما كسبوا، لهم شراب من حميم وعذاب أليم بما كانوا يكفرون.", "h": ["حرمة الجلوس في مجالس يُسخر فيها من الإسلام وشرائعه وأحكامه وأهله.", "وجوب القيام احتجاجاً من أي مجلس يُعصى فيه الله ورسوله.", "مشروعية الإعراض في حال الضعف عن المستهزئين بالإسلام من أهل القوة والسلطان، وحسب المؤمن أن يُعرض عنهم فلا يفرح بهم ولا يضحك لهم.", "وجوب التذكير بالقرآن، وخاصة المؤمنين الذين تُرجى توبتهم.", "من مات على كفره لم ينجُ من النار."], "k": "«فلا تقعد بعد الذكرى مع القوم الظالمين»… هل أقوم من مجلس يُستهزأ فيه بدين الله، أم أبقى مجاملةً؟"}, {"lbl": "الآيات ٧١ – ٧٣", "q": "قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ﴿٧١﴾ وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٧٢﴾ وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ ﴿٧٣﴾", "w": [["أندعو", "أي أنعبد."], ["ما لا ينفعنا ولا يضرّنا", "ما لا يقدر على نفعنا ولا على ضرّنا لو أراد ذلك لنا."], ["ونُردّ على أعقابنا", "نرجع كفاراً بعد أن كنا مؤمنين."], ["استهوته الشياطين", "أضلّته في الأرض فهوى فيها تائهاً حيران لا يدري أين يذهب."], ["واتقوه", "اتقوا الله بتوحيده في عبادته وترك معصيته."], ["ويوم يقول كن فيكون", "أي يوم القيامة."], ["الصور", "بوق كالقرن ينفخ فيه إسرافيل ﵇."], ["الحكيم الخبير", "الحكيم في أفعاله، الخبير بأحوال عباده."]], "m": "يدل السياق على أن المشركين عرضوا على بعض المؤمنين أن يعبدوا معهم آلهتهم، فأمر الله رسوله أن يردّ عرضهم منكراً: قل أندعو من دون الله ما لا ينفعنا إن عبدناه ولا يضرّنا إن تركناه، ونُردّ على أعقابنا من التوحيد إلى الشرك بعد إذ هدانا الله؟ فيكون حالنا كمن أضلّته الشياطين في الصحراء فتاه حيران، له أصحاب يدعونه إلى الهدى: ائتنا، وهو لا يقدر على إجابتهم. قل إن هدى الله هو الهدى، وهو الإسلام، وأُمرنا لنُسلم لرب العالمين فأسلمنا، وأن أقيموا الصلاة واتقوه فأقمناها واتقيناه، وهو الذي إليه تُحشرون. وهو الذي خلق السماوات والأرض بالحق لا عبثاً، ويوم يقول كن فيكون، قوله الحق، وله الملك يوم يُنفخ في الصور نفخة الفناء، عالم الغيب والشهادة، وهو الحكيم في تصرفاته الخبير ببواطن الأمور وظواهرها، فهو المعبود الحق الذي لا يُعبد سواه.", "h": ["قبح الردة وسوء عاقبتها.", "حرمة إجابة أهل الباطل لما يدعون إليه من الباطل.", "لا هدى إلا هدى الله تعالى، أي لا دين إلا الإسلام.", "وجوب الإسلام لله تعالى، وإقامة الصلاة، واتقاء الله بفعل المأمور وترك المنهي.", "تقرير المعاد والحساب والجزاء."], "k": "«كالذي استهوته الشياطين في الأرض حيران»… من الأصحاب الذين يدعونني إلى الهدى، وهل أستجيب لهم؟"}, {"lbl": "الآيات ٧٤ – ٧٩", "q": "۞وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٧٤﴾ وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ ﴿٧٥﴾ فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ ﴿٧٦﴾ فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ ﴿٧٧﴾ فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ﴿٧٨﴾ إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ﴿٧٩﴾", "w": [["إبراهيم", "خليل الرحمن ﵇، من أولاد سام بن نوح ﵇."], ["آلهة", "جمع إله بمعنى المعبود."], ["في ضلال", "عدول عن طريق الحق."], ["ملكوت", "ملك."], ["جنّ عليه الليل", "أظلم."], ["أفل", "غاب."], ["بازغاً", "طالعاً، والبزوغ: الطلوع."], ["الضالين", "العادلين عن طريق الحق إلى طريق الباطل."], ["وجّهت وجهي", "أقبلت بقلبي على ربي وأعرضت عما سواه."], ["حنيفاً", "مائلاً عن الضلال إلى الهدى."]], "m": "ما زال السياق في بيان الهدى للعادلين بربهم أصناماً، فقال لرسوله ﷺ: واذكر لهم قول إبراهيم لأبيه آزر: أتتخذ تماثيل من حجارة آلهة تعبدها؟ إني أراك وقومك في ضلال مبين عن طريق الحق. وكما أريناه بطلان عبادة الأصنام نريه ملكوت السماوات والأرض ومظاهر قدرتنا وعلمنا وحكمتنا، ليكون من الموقنين، واليقين من أعلى مراتب الإيمان. فلما أظلم عليه الليل رأى كوكباً قال: هذا ربي، فلما غاب قال: لا أحب الآفلين، فلما رأى القمر طالعاً قال: هذا ربي، فلما غاب قال: لئن لم يهدني ربي لأكوننّ من القوم الضالين، فلما رأى الشمس طالعة قال: هذا ربي هذا أكبر، فلما غابت قال: يا قوم إني بريء مما تشركون. هكذا واجه إبراهيم قومه عبدة الكواكب التي تمثّلها أصنامهم المنحوتة بالحقيقة التي أراد أن يصل إليها معهم، وهي إبطال عبادة غير الله، فقال: إني وجّهت وجهي للذي فطر السماوات والأرض حنيفاً وما أنا من المشركين.", "h": ["إنكار الشرك على أهله، وعدم إقرارهم عليه ولو كانوا أقرب الناس إلى المرء.", "فضل الله تعالى وتفضّله على من يشاء بالهداية الموصلة إلى أعلى درجاتها.", "مطلب اليقين من أشرف المطالب وأعزّها، ويتم بالتفكر والنظر في الآيات.", "الاستدلال بالحدوث على وجود الصانع الحكيم، وهو الله عز وجل.", "سنة التدرج في التربية والتعليم.", "وجوب البراءة من الشرك وأهله."], "k": "«لا أحب الآفلين»… كم شيئاً في حياتي يغيب ويزول، وقلبي معلّق به أكثر من تعلّقه بالحي الذي لا يغيب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 91;
insert into public.tdb_cards(topic, i, body) select 91, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٣ – ٦٧", "q": "قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿٦٣﴾ قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ ﴿٦٤﴾ قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ ﴿٦٥﴾ وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ ﴿٦٦﴾ لِّكُلِّ نَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ ﴿٦٧﴾", "w": [["ينجيكم", "يخلّصكم مما تخافون."], ["تضرّعاً وخفية", "التضرع: الدعاء بتذلّل، وخفية: بدون جهر بالدعاء."], ["من هذه", "أي من هذه المهلكة."], ["من الشاكرين", "المعترفين بفضلك، الحامدين لك على فعلك."], ["كرب", "الشدة الموجبة للحزن وألم الجسم والنفس."], ["تشركون", "أي به تعالى، بدعائكم أصنامكم وتقرّبكم إليها بالذبائح."], ["من فوقكم", "كالصواعق ونحوها."], ["من تحت أرجلكم", "كالزلازل والخسف ونحوهما."], ["أو يلبسكم شيعاً", "يخلط عليكم أمركم فتختلفون شيعاً وأحزاباً."], ["ويذيق بعضكم بأس بعض", "يقتل بعضكم بعضاً، فتذيق كل طائفة الأخرى ألم الحرب."], ["يفقهون", "يفهمون معاني ما نقول لهم."], ["وكذّب به قومك", "أي قريش."], ["الوكيل", "من يوكَل إليه الأمر يدبّره."], ["لكل نبأ مستقر", "المستقر: موضع الاستقرار، والنبأ: الخبر العظيم."]], "m": "ما زال السياق مع المشركين: قل لهم من ينجيكم من ظلمات البر والبحر؟ إذا ضلّ أحدكم طريقه في الصحراء وأظلم عليه الليل، أو ركب البحر فغشيته الظلمات واضطربت نفسه، يدعو من؟ يدعو الله وحده متضرّعاً جهراً وسراً: لئن أنجانا من هذه لنكوننّ من الشاكرين. قل الله ينجيكم منها ومن كل كرب، ثم يا للعجب أنتم تشركون به أصنامكم! قل هو القادر على أن يبعث عليكم عذاباً من فوقكم أو من تحت أرجلكم، أو يخلط عليكم أمركم فتصبحوا شيعاً وفرقاً متعادية يقتل بعضكم بعضاً. انظر كيف ننوّع الكلام ونوضّح معانيه رجاء أن يفقهوا فيهتدوا. وكذّب به قومك وهو الحق، قل لست عليكم بوكيل، ولكل نبأ مستقر وسوف تعلمون، وقد استقر نبؤه يوم بدر.", "h": ["لا برهان أعظم على بطلان الشرك من أن المشركين يُخلصون الدعاء لله تعالى في الشدة.", "لا منجى من الشدائد ولا منقذ من الكروب إلا الله سبحانه وتعالى.", "التحذير من الاختلاف المفضي إلى الانقسام والتكتل."], "k": "في الشدة لا أدعو إلا الله… فهل بقيت على الإخلاص نفسه بعد أن نجّاني؟"}, {"lbl": "الآيات ٦٨ – ٧٠", "q": "وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٦٨﴾ وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ ﴿٦٩﴾ وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ وَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ ﴿٧٠﴾", "w": [["يخوضون في آياتنا", "يتكلمون في القرآن طعناً فيه ونقداً له ولما جاء فيه."], ["بعد الذكرى", "بعد التذكّر."], ["ولكن ذكرى", "أي موعظة لهم."], ["وذر الذين", "اترك الكافرين."], ["لعباً ولهواً", "لعباً لأنهم لا يجنون منه فائدة قط، ولهواً لأنهم يتلهّون به عن الدين الحق."], ["أن تُبسل نفس", "تُسلم فتؤخذ فتُحبس في جهنم."], ["كل عدل", "العدل هنا: الفداء."], ["أُبسلوا", "حُبسوا في جهنم بما كسبوا من الشرك والمعاصي."], ["من حميم", "الماء الشديد الحرارة الذي لا يطاق."], ["وعذاب أليم", "شديد الألم والإيجاع، وهو عذاب النار."]], "m": "يقول الله لرسوله: وإذا رأيت الذين يخوضون في آياتنا يستهزئون بها ويسخرون مما دلّت عليه، فأعرض عنهم وانصرف حتى يخوضوا في حديث غيره، وإن أنساك الشيطان فجلست ثم ذكرت فقم ولا تقعد مع القوم الظالمين. وليس على المتقين من تبعة حسابهم شيء، ولكن إذا خاضوا في الباطل فقوموا ليكون ذلك ذكرى لهم فيكفّوا. وكان هذا بمكة قبل قوة الإسلام، ثم نزل بالمدينة النهي عن الجلوس معهم إذا خاضوا، وأن من جلس معهم كان مثلهم. وذر الذين اتخذوا دينهم لعباً ولهواً وغرّتهم الحياة الدنيا، وذكّر بالقرآن كي لا تُسلم نفس للعذاب بما كسبت، ليس لها من دون الله ولي ولا شفيع، وإن تقدّم كل فداء ولو ملء الأرض ذهباً لا يؤخذ منها. أولئك الذين أُبسلوا بما كسبوا، لهم شراب من حميم وعذاب أليم بما كانوا يكفرون.", "h": ["حرمة الجلوس في مجالس يُسخر فيها من الإسلام وشرائعه وأحكامه وأهله.", "وجوب القيام احتجاجاً من أي مجلس يُعصى فيه الله ورسوله.", "مشروعية الإعراض في حال الضعف عن المستهزئين بالإسلام من أهل القوة والسلطان، وحسب المؤمن أن يُعرض عنهم فلا يفرح بهم ولا يضحك لهم.", "وجوب التذكير بالقرآن، وخاصة المؤمنين الذين تُرجى توبتهم.", "من مات على كفره لم ينجُ من النار."], "k": "«فلا تقعد بعد الذكرى مع القوم الظالمين»… هل أقوم من مجلس يُستهزأ فيه بدين الله، أم أبقى مجاملةً؟"}, {"lbl": "الآيات ٧١ – ٧٣", "q": "قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ﴿٧١﴾ وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٧٢﴾ وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ ﴿٧٣﴾", "w": [["أندعو", "أي أنعبد."], ["ما لا ينفعنا ولا يضرّنا", "ما لا يقدر على نفعنا ولا على ضرّنا لو أراد ذلك لنا."], ["ونُردّ على أعقابنا", "نرجع كفاراً بعد أن كنا مؤمنين."], ["استهوته الشياطين", "أضلّته في الأرض فهوى فيها تائهاً حيران لا يدري أين يذهب."], ["واتقوه", "اتقوا الله بتوحيده في عبادته وترك معصيته."], ["ويوم يقول كن فيكون", "أي يوم القيامة."], ["الصور", "بوق كالقرن ينفخ فيه إسرافيل ﵇."], ["الحكيم الخبير", "الحكيم في أفعاله، الخبير بأحوال عباده."]], "m": "يدل السياق على أن المشركين عرضوا على بعض المؤمنين أن يعبدوا معهم آلهتهم، فأمر الله رسوله أن يردّ عرضهم منكراً: قل أندعو من دون الله ما لا ينفعنا إن عبدناه ولا يضرّنا إن تركناه، ونُردّ على أعقابنا من التوحيد إلى الشرك بعد إذ هدانا الله؟ فيكون حالنا كمن أضلّته الشياطين في الصحراء فتاه حيران، له أصحاب يدعونه إلى الهدى: ائتنا، وهو لا يقدر على إجابتهم. قل إن هدى الله هو الهدى، وهو الإسلام، وأُمرنا لنُسلم لرب العالمين فأسلمنا، وأن أقيموا الصلاة واتقوه فأقمناها واتقيناه، وهو الذي إليه تُحشرون. وهو الذي خلق السماوات والأرض بالحق لا عبثاً، ويوم يقول كن فيكون، قوله الحق، وله الملك يوم يُنفخ في الصور نفخة الفناء، عالم الغيب والشهادة، وهو الحكيم في تصرفاته الخبير ببواطن الأمور وظواهرها، فهو المعبود الحق الذي لا يُعبد سواه.", "h": ["قبح الردة وسوء عاقبتها.", "حرمة إجابة أهل الباطل لما يدعون إليه من الباطل.", "لا هدى إلا هدى الله تعالى، أي لا دين إلا الإسلام.", "وجوب الإسلام لله تعالى، وإقامة الصلاة، واتقاء الله بفعل المأمور وترك المنهي.", "تقرير المعاد والحساب والجزاء."], "k": "«كالذي استهوته الشياطين في الأرض حيران»… من الأصحاب الذين يدعونني إلى الهدى، وهل أستجيب لهم؟"}, {"lbl": "الآيات ٧٤ – ٧٩", "q": "۞وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٧٤﴾ وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ ﴿٧٥﴾ فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ ﴿٧٦﴾ فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ ﴿٧٧﴾ فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ﴿٧٨﴾ إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ﴿٧٩﴾", "w": [["إبراهيم", "خليل الرحمن ﵇، من أولاد سام بن نوح ﵇."], ["آلهة", "جمع إله بمعنى المعبود."], ["في ضلال", "عدول عن طريق الحق."], ["ملكوت", "ملك."], ["جنّ عليه الليل", "أظلم."], ["أفل", "غاب."], ["بازغاً", "طالعاً، والبزوغ: الطلوع."], ["الضالين", "العادلين عن طريق الحق إلى طريق الباطل."], ["وجّهت وجهي", "أقبلت بقلبي على ربي وأعرضت عما سواه."], ["حنيفاً", "مائلاً عن الضلال إلى الهدى."]], "m": "ما زال السياق في بيان الهدى للعادلين بربهم أصناماً، فقال لرسوله ﷺ: واذكر لهم قول إبراهيم لأبيه آزر: أتتخذ تماثيل من حجارة آلهة تعبدها؟ إني أراك وقومك في ضلال مبين عن طريق الحق. وكما أريناه بطلان عبادة الأصنام نريه ملكوت السماوات والأرض ومظاهر قدرتنا وعلمنا وحكمتنا، ليكون من الموقنين، واليقين من أعلى مراتب الإيمان. فلما أظلم عليه الليل رأى كوكباً قال: هذا ربي، فلما غاب قال: لا أحب الآفلين، فلما رأى القمر طالعاً قال: هذا ربي، فلما غاب قال: لئن لم يهدني ربي لأكوننّ من القوم الضالين، فلما رأى الشمس طالعة قال: هذا ربي هذا أكبر، فلما غابت قال: يا قوم إني بريء مما تشركون. هكذا واجه إبراهيم قومه عبدة الكواكب التي تمثّلها أصنامهم المنحوتة بالحقيقة التي أراد أن يصل إليها معهم، وهي إبطال عبادة غير الله، فقال: إني وجّهت وجهي للذي فطر السماوات والأرض حنيفاً وما أنا من المشركين.", "h": ["إنكار الشرك على أهله، وعدم إقرارهم عليه ولو كانوا أقرب الناس إلى المرء.", "فضل الله تعالى وتفضّله على من يشاء بالهداية الموصلة إلى أعلى درجاتها.", "مطلب اليقين من أشرف المطالب وأعزّها، ويتم بالتفكر والنظر في الآيات.", "الاستدلال بالحدوث على وجود الصانع الحكيم، وهو الله عز وجل.", "سنة التدرج في التربية والتعليم.", "وجوب البراءة من الشرك وأهله."], "k": "«لا أحب الآفلين»… كم شيئاً في حياتي يغيب ويزول، وقلبي معلّق به أكثر من تعلّقه بالحي الذي لا يغيب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (92, 6, 80, 90, 'سورة الأنعام ٨٠ – ٩٠', '«الذين آمنوا ولم يلبسوا إيمانهم بظلم»، والأنبياء من ذرية إبراهيم ﵇: «فبهداهم اقتده»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 92) = $j$[{"lbl": "الآيات ٨٠ – ٨٣", "q": "وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَـٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـٔٗاۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ ﴿٨٠﴾ وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٨١﴾ ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَـٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ ﴿٨٢﴾ وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ ﴿٨٣﴾", "w": [["حاجّه قومه", "جادلوه وحاولوا غلبه بالحجة، والحجة: البيّنة والدليل القوي."], ["أتحاجّونّي في الله", "أتجادلونني في توحيد الله وقد هداني إليه، فكيف أتركه وأنا منه على بيّنة؟"], ["سلطاناً", "حجة وبرهاناً."], ["الأمن", "خلاف الخوف."], ["ولم يلبسوا إيمانهم بظلم", "لم يخلطوا إيمانهم بشرك."]], "m": "لما أقام إبراهيم الدليل على بطلان عبادة غير الله وتبرّأ من الشرك والمشركين، جادله قومه، فقال منكراً: أتحاجّونّي في الله وقد هداني إلى معرفته وتوحيده؟ ولما خوّفوه أن تصيبه آلهتهم بسوء قال: ولا أخاف ما تشركون به إلا أن يشاء ربي شيئاً، وسع ربي كل شيء علماً، أفلا تتذكرون؟ وكيف أخاف أصنامكم الجامدة التي لا تنفع ولا تضر، ولا تخافون أنتم أنكم أشركتم بالله ما لم ينزّل به عليكم حجة ولا برهاناً؟ فأي الفريقين أحق بالأمن: أنا الموحّد، أم أنتم المشركون؟ والجواب معروف. وفصل الله بينهم: الذين آمنوا ولم يخلطوا إيمانهم بشرك أولئك لهم الأمن في الدنيا والآخرة وهم مهتدون. وتلك حجتنا آتيناها إبراهيم على قومه، نرفع درجات من نشاء بالإيمان واليقين والعلم، إن ربك حكيم في تدبيره عليم بخلقه.", "h": ["مشروعية جدال المبطلين والمشركين لإقامة الحجة عليهم، علّهم يهتدون.", "بيان ضلال عقول أهل الشرك في كل زمان ومكان.", "التعجب من حال مذنب لا يخاف عاقبة ذنوبه.", "أحق العباد بالأمن من الخوف من آمن بالله ولم يشرك به شيئاً.", "تقرير معنى «الله ولي الذين آمنوا يخرجهم من الظلمات إلى النور»."], "k": "«أولئك لهم الأمن»… هل أبحث عن الأمان في المال والناس، وهو في إيمان لا يخالطه شرك؟"}, {"lbl": "الآيات ٨٤ – ٨٧", "q": "وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٨٤﴾ وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّـٰلِحِينَ ﴿٨٥﴾ وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ ﴿٨٦﴾ وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّـٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٨٧﴾", "w": [["ووهبنا له", "أعطيناه تكرّماً منا وإفضالاً."], ["إسحاق ويعقوب", "إسحاق بن إبراهيم الخليل، ويعقوب ولد إسحاق ويُلقّب بإسرائيل."], ["كلاً هدينا", "كل واحد منهما هديناه إلى صراطه المستقيم."], ["ومن ذريته", "أي ذرية إبراهيم."], ["داود وسليمان", "داود الوالد وسليمان الولد، وكل منهما ملك ورسول."], ["وزكريا ويحيى", "زكريا الوالد ويحيى الولد، وكل منهما كان نبياً رسولاً."], ["على العالمين", "عالمي زمانهم لا على الإطلاق، لأن محمداً ﷺ أفضل الأنبياء."], ["ومن ذرياتهم", "من بعض الآباء والذرية والإخوة لا الجميع."], ["اجتبيناهم", "اخترناهم للنبوة والرسالة، وهديناهم إلى الإسلام."]], "m": "بعد أن ذكر الله ما آتى خليله من قوة الحجة، ذكر منّة أخرى: أنه وهبه إسحاق ويعقوب بعد كبر سنّه، الولد والحفيد، وهداهم جميعاً، وهدى نوحاً من قبل، ومن ذرية إبراهيم داود وسليمان وأيوب ويوسف وموسى وهارون، وكذلك نجزي المحسنين، والإحسان هو الإخلاص في العمل وأداؤه على الوجه الذي يرضي الرب، مع الإحسان إلى سائر المخلوقات. وزكريا ويحيى وعيسى وإلياس كلٌّ من الصالحين الذين يؤدّون حقوق الله وحقوق عباده كاملة. وكانت الصفة الغالبة على المجموعة الأولى الإحسان، لأنه كان فيهم ملك وسلطان ودولة، وعلى الثانية الصلاح، لأنهم كانوا أهل زهد في الدنيا. وإسماعيل واليسع ويونس ولوطاً، وهم وسط بين المجموعتين، وكلاً فضّلنا على العالمين في زمانه. ومن آبائهم وذرياتهم وإخوانهم ممن لم تُذكر أسماؤهم، واجتبيناهم للنبوة والرسالة وهديناهم إلى صراط مستقيم، وهو الدين الإسلامي.", "h": ["سعة فضل الله.", "خير ما يُعطى المرء في هذه الحياة الهداية إلى صراط مستقيم.", "فضيلة كل من الإحسان والصلاح.", "لا منافاة بين الملك والنبوة، أو الإمارة والصلاح.", "فضيلة الزهد في الدنيا والرغبة في الآخرة."], "k": "«وكذلك نجزي المحسنين»… هل أُتقن عملي ليرضى ربي، وأُحسن إلى من حولي قولاً وفعلاً؟"}, {"lbl": "الآيات ٨٨ – ٩٠", "q": "ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ ﴿٨٨﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَـٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ ﴿٨٩﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ ﴿٩٠﴾", "w": [["هدى الله", "الهدى ضد الضلال، وهدى الله ما يهدي إليه من أحب من عباده، وهو الإيمان والاستقامة."], ["حبط عنهم ما كانوا يعملون", "بطلت أعمالهم فلم يُثابوا عليها بقليل ولا كثير."], ["الحكم", "الفهم للكتاب مع الإصابة في الأمور والسداد فيها."], ["يكفر بها هؤلاء", "يجحد بها، أي بدعوتك الإسلامية، هؤلاء أي أهل مكة."], ["قوماً ليسوا بها بكافرين", "هم المهاجرون والأنصار بالمدينة النبوية."], ["اقتده", "اقتدِ، أي اتّبع، وزيدت الهاء للسكت."], ["عليه أجراً", "أي على إبلاغ دعوة الإسلام ثمناً مقابل الإبلاغ."], ["ذكرى", "ما يُذكَّر به الغافل والناسي فيتّعظ."]], "m": "ذلك الذي وهبه الله هؤلاء الرسل الثمانية عشر من النبوة والدين الحق هو هدى الله يهدي به من يشاء من عباده. ولو أشركوا لحبط عنهم ما كانوا يعملون، وهذا يقرّر أن الشرك محبط للعمل، فلو أشرك هؤلاء على كمالهم لبطل عملهم، وهو من باب الافتراض، فالرسل معصومون، ولكن ليكون عظة للناس. أولئك الذين آتيناهم الكتاب: صحف إبراهيم وتوراة موسى وزبور داود وإنجيل عيسى، والحكم والنبوة، فإن يكفر بها أهل مكة فقد وكّلنا بها قوماً ليسوا بها بكافرين: الرسل المذكورين، والمهاجرين والأنصار ومن يأتي بعدهم من سائر البلاد. أولئك الذين هدى الله فبهداهم اقتده، يأمر رسوله ﷺ أن يقتدي بهم في كمالاتهم كلها، حتى يجمع كل كمال فيهم فيصبح أكملهم على الإطلاق، وكذلك كان. قل لا أسألكم على القرآن أجراً، إن هو إلا ذكرى للعالمين، يتّعظون بها إن ألقوا أسماعهم وتجرّدوا من أهوائهم.", "h": ["الشرك محبط للعمل كالردة، والعياذ بالله تعالى.", "فضل الكتاب الكريم والسنة النبوية.", "وجوب الاقتداء بالرسول ﷺ وأهل العلم والصلاح من هذه الأمة.", "حرمة أخذ الأجرة على تبليغ الدعوة الإسلامية.", "القرآن الكريم ذكرى لكل من يقرؤه أو يستمع إليه وهو شهيد حاضر القلب."], "k": "«فبهداهم اقتده»… أيّ خُلُق من أخلاق الأنبياء أحتاج أن أقتدي به اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 92;
insert into public.tdb_cards(topic, i, body) select 92, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٠ – ٨٣", "q": "وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَـٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـٔٗاۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ ﴿٨٠﴾ وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٨١﴾ ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَـٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ ﴿٨٢﴾ وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ ﴿٨٣﴾", "w": [["حاجّه قومه", "جادلوه وحاولوا غلبه بالحجة، والحجة: البيّنة والدليل القوي."], ["أتحاجّونّي في الله", "أتجادلونني في توحيد الله وقد هداني إليه، فكيف أتركه وأنا منه على بيّنة؟"], ["سلطاناً", "حجة وبرهاناً."], ["الأمن", "خلاف الخوف."], ["ولم يلبسوا إيمانهم بظلم", "لم يخلطوا إيمانهم بشرك."]], "m": "لما أقام إبراهيم الدليل على بطلان عبادة غير الله وتبرّأ من الشرك والمشركين، جادله قومه، فقال منكراً: أتحاجّونّي في الله وقد هداني إلى معرفته وتوحيده؟ ولما خوّفوه أن تصيبه آلهتهم بسوء قال: ولا أخاف ما تشركون به إلا أن يشاء ربي شيئاً، وسع ربي كل شيء علماً، أفلا تتذكرون؟ وكيف أخاف أصنامكم الجامدة التي لا تنفع ولا تضر، ولا تخافون أنتم أنكم أشركتم بالله ما لم ينزّل به عليكم حجة ولا برهاناً؟ فأي الفريقين أحق بالأمن: أنا الموحّد، أم أنتم المشركون؟ والجواب معروف. وفصل الله بينهم: الذين آمنوا ولم يخلطوا إيمانهم بشرك أولئك لهم الأمن في الدنيا والآخرة وهم مهتدون. وتلك حجتنا آتيناها إبراهيم على قومه، نرفع درجات من نشاء بالإيمان واليقين والعلم، إن ربك حكيم في تدبيره عليم بخلقه.", "h": ["مشروعية جدال المبطلين والمشركين لإقامة الحجة عليهم، علّهم يهتدون.", "بيان ضلال عقول أهل الشرك في كل زمان ومكان.", "التعجب من حال مذنب لا يخاف عاقبة ذنوبه.", "أحق العباد بالأمن من الخوف من آمن بالله ولم يشرك به شيئاً.", "تقرير معنى «الله ولي الذين آمنوا يخرجهم من الظلمات إلى النور»."], "k": "«أولئك لهم الأمن»… هل أبحث عن الأمان في المال والناس، وهو في إيمان لا يخالطه شرك؟"}, {"lbl": "الآيات ٨٤ – ٨٧", "q": "وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٨٤﴾ وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّـٰلِحِينَ ﴿٨٥﴾ وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ ﴿٨٦﴾ وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّـٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٨٧﴾", "w": [["ووهبنا له", "أعطيناه تكرّماً منا وإفضالاً."], ["إسحاق ويعقوب", "إسحاق بن إبراهيم الخليل، ويعقوب ولد إسحاق ويُلقّب بإسرائيل."], ["كلاً هدينا", "كل واحد منهما هديناه إلى صراطه المستقيم."], ["ومن ذريته", "أي ذرية إبراهيم."], ["داود وسليمان", "داود الوالد وسليمان الولد، وكل منهما ملك ورسول."], ["وزكريا ويحيى", "زكريا الوالد ويحيى الولد، وكل منهما كان نبياً رسولاً."], ["على العالمين", "عالمي زمانهم لا على الإطلاق، لأن محمداً ﷺ أفضل الأنبياء."], ["ومن ذرياتهم", "من بعض الآباء والذرية والإخوة لا الجميع."], ["اجتبيناهم", "اخترناهم للنبوة والرسالة، وهديناهم إلى الإسلام."]], "m": "بعد أن ذكر الله ما آتى خليله من قوة الحجة، ذكر منّة أخرى: أنه وهبه إسحاق ويعقوب بعد كبر سنّه، الولد والحفيد، وهداهم جميعاً، وهدى نوحاً من قبل، ومن ذرية إبراهيم داود وسليمان وأيوب ويوسف وموسى وهارون، وكذلك نجزي المحسنين، والإحسان هو الإخلاص في العمل وأداؤه على الوجه الذي يرضي الرب، مع الإحسان إلى سائر المخلوقات. وزكريا ويحيى وعيسى وإلياس كلٌّ من الصالحين الذين يؤدّون حقوق الله وحقوق عباده كاملة. وكانت الصفة الغالبة على المجموعة الأولى الإحسان، لأنه كان فيهم ملك وسلطان ودولة، وعلى الثانية الصلاح، لأنهم كانوا أهل زهد في الدنيا. وإسماعيل واليسع ويونس ولوطاً، وهم وسط بين المجموعتين، وكلاً فضّلنا على العالمين في زمانه. ومن آبائهم وذرياتهم وإخوانهم ممن لم تُذكر أسماؤهم، واجتبيناهم للنبوة والرسالة وهديناهم إلى صراط مستقيم، وهو الدين الإسلامي.", "h": ["سعة فضل الله.", "خير ما يُعطى المرء في هذه الحياة الهداية إلى صراط مستقيم.", "فضيلة كل من الإحسان والصلاح.", "لا منافاة بين الملك والنبوة، أو الإمارة والصلاح.", "فضيلة الزهد في الدنيا والرغبة في الآخرة."], "k": "«وكذلك نجزي المحسنين»… هل أُتقن عملي ليرضى ربي، وأُحسن إلى من حولي قولاً وفعلاً؟"}, {"lbl": "الآيات ٨٨ – ٩٠", "q": "ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ ﴿٨٨﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَـٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ ﴿٨٩﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ ﴿٩٠﴾", "w": [["هدى الله", "الهدى ضد الضلال، وهدى الله ما يهدي إليه من أحب من عباده، وهو الإيمان والاستقامة."], ["حبط عنهم ما كانوا يعملون", "بطلت أعمالهم فلم يُثابوا عليها بقليل ولا كثير."], ["الحكم", "الفهم للكتاب مع الإصابة في الأمور والسداد فيها."], ["يكفر بها هؤلاء", "يجحد بها، أي بدعوتك الإسلامية، هؤلاء أي أهل مكة."], ["قوماً ليسوا بها بكافرين", "هم المهاجرون والأنصار بالمدينة النبوية."], ["اقتده", "اقتدِ، أي اتّبع، وزيدت الهاء للسكت."], ["عليه أجراً", "أي على إبلاغ دعوة الإسلام ثمناً مقابل الإبلاغ."], ["ذكرى", "ما يُذكَّر به الغافل والناسي فيتّعظ."]], "m": "ذلك الذي وهبه الله هؤلاء الرسل الثمانية عشر من النبوة والدين الحق هو هدى الله يهدي به من يشاء من عباده. ولو أشركوا لحبط عنهم ما كانوا يعملون، وهذا يقرّر أن الشرك محبط للعمل، فلو أشرك هؤلاء على كمالهم لبطل عملهم، وهو من باب الافتراض، فالرسل معصومون، ولكن ليكون عظة للناس. أولئك الذين آتيناهم الكتاب: صحف إبراهيم وتوراة موسى وزبور داود وإنجيل عيسى، والحكم والنبوة، فإن يكفر بها أهل مكة فقد وكّلنا بها قوماً ليسوا بها بكافرين: الرسل المذكورين، والمهاجرين والأنصار ومن يأتي بعدهم من سائر البلاد. أولئك الذين هدى الله فبهداهم اقتده، يأمر رسوله ﷺ أن يقتدي بهم في كمالاتهم كلها، حتى يجمع كل كمال فيهم فيصبح أكملهم على الإطلاق، وكذلك كان. قل لا أسألكم على القرآن أجراً، إن هو إلا ذكرى للعالمين، يتّعظون بها إن ألقوا أسماعهم وتجرّدوا من أهوائهم.", "h": ["الشرك محبط للعمل كالردة، والعياذ بالله تعالى.", "فضل الكتاب الكريم والسنة النبوية.", "وجوب الاقتداء بالرسول ﷺ وأهل العلم والصلاح من هذه الأمة.", "حرمة أخذ الأجرة على تبليغ الدعوة الإسلامية.", "القرآن الكريم ذكرى لكل من يقرؤه أو يستمع إليه وهو شهيد حاضر القلب."], "k": "«فبهداهم اقتده»… أيّ خُلُق من أخلاق الأنبياء أحتاج أن أقتدي به اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;